1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	const POINT_FOR_THE_SPHINX_ITSELF = 1;
8	const MINIMUM_COMPANY_BONUS = 1;
9	const COMPANY_TYPE_THRESHOLD = 3;
10	const POINTS_PER_COMPANY_TYPE_BEYOND_THRESHOLD = 2;
11	
12	/**
13	 * What makes two cards the same type for scoring. Rank is deliberately
14	 * ignored: an Undead Warrior of rank 1 and one of rank 3 are one type, not two.
15	 */
16	const typeOf = (card: Card): string => card.monster;
17	
18	/**
19	 * The distinct monster types keeping one card company — every other card in
20	 * the army, the card itself excluded. A second Sphinx is company like any
21	 * other monster.
22	 */
23	const countCompanyTypes = (army: Card[], cardIndex: number): number =>
24	  new Set(army.filter((_, index) => index !== cardIndex).map(typeOf)).size;
25	
26	/** What one Sphinx earns from the variety of monsters around it. */
27	const scoreOneSphinx = (army: Card[], cardIndex: number): number => {
28	  const companyTypesBeyondThreshold =
29	    countCompanyTypes(army, cardIndex) - COMPANY_TYPE_THRESHOLD;
30	  const companyBonus = Math.max(
31	    POINTS_PER_COMPANY_TYPE_BEYOND_THRESHOLD * companyTypesBeyondThreshold,
32	    MINIMUM_COMPANY_BONUS,
33	  );
34	  return POINT_FOR_THE_SPHINX_ITSELF + companyBonus;
35	};
36	
37	export const scoreArmy = (army: Card[]): number =>
38	  army.reduce(
39	    (total, card, index) =>
40	      card.monster === SPHINX ? total + scoreOneSphinx(army, index) : total,
41	    0,
42	  );
43

